import products from './products.json' with {type:'json'};

export async function listTools() {
  return [
    {
      name: 'inventory_search',
      description: 'Search inventory products by name (case-insensitive).',
      inputSchema: {
        type: 'object',
        properties: {
          query: { type: 'string', description: 'Search term to match against product names.' },
          limit: { type: 'integer', minimum: 1, maximum: 10, description: 'Maximum number of results to return (1-10).' }
        },
        required: ['query'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args = {}) {
  if (name !== 'inventory_search') {
    throw new Error(`Unknown tool: ${name}`);
  }
  const { query, limit } = args;
  if (typeof query !== 'string') {
    throw new Error('query must be a string');
  }
  let effectiveLimit;
  if (limit === undefined) {
    effectiveLimit = null;
  } else {
    if (!Number.isInteger(limit)) {
      throw new Error('limit must be an integer');
    }
    if (limit < 1 || limit > 10) {
      throw new Error('limit must be between 1 and 10');
    }
    effectiveLimit = limit;
  }
  // check for extra args
  const allowed = new Set(['query', 'limit']);
  for (const key of Object.keys(args)) {
    if (!allowed.has(key)) {
      throw new Error(`Unknown argument: ${key}`);
    }
  }

  const q = query.toLowerCase();
  let matches = products.filter(p => p.name.toLowerCase().includes(q));
  if (effectiveLimit !== null) {
    matches = matches.slice(0, effectiveLimit);
  }

  const text = matches.length === 0
    ? 'No matching products found.'
    : matches.map(p => `${p.id}: ${p.name}`).join('\n');

  return {
    content: [{ type: 'text', text }]
  };
}
```

